import re
import pandas as pd

def micom_exchange_table(com):
    """Return MICOM community exchange reactions as a DataFrame."""
    rows = []
    for r in com.exchanges:
        mets = list(r.metabolites)
        met = mets[0] if mets else None
        rows.append({
            "reaction": r.id,
            "name": r.name,
            "metabolite": met.id if met is not None else "",
            "metabolite_name": met.name if met is not None else "",
            "formula": getattr(met, "formula", "") if met is not None else "",
            "lower_bound": r.lower_bound,
            "upper_bound": r.upper_bound,
        })
    return pd.DataFrame(rows)


def build_micom_medium_from_gapseq(com, medium_csv):
    """
    Convert a gapseq medium CSV with columns 'compounds' and 'maxFlux'
    into a MICOM community medium.

    MICOM expects community exchange reaction IDs as keys and positive
    import fluxes as values, e.g. {'EX_cpd00027_m': 10.0}.
    """
    medium_df = pd.read_csv(medium_csv)
    exchange_ids = {r.id for r in com.exchanges}

    # Map cpd IDs to MICOM exchange IDs actually present in the community.
    exchange_by_cpd = {}
    for rid in exchange_ids:
        match = re.search(r"(cpd\d+)", rid)
        if match:
            exchange_by_cpd.setdefault(match.group(1), []).append(rid)

    medium = {}
    rows = []

    for _, row in medium_df.iterrows():
        cpd = str(row["compounds"]).strip()
        max_flux = float(row["maxFlux"])

        direct_candidates = [
            f"EX_{cpd}_m",
            f"EX_{cpd}_e0_m",
            f"EX_{cpd}_e_m",
            f"R_EX_{cpd}_m",
            f"R_EX_{cpd}_e0_m",
            f"R_EX_{cpd}_e_m",
        ]

        rid = next((candidate for candidate in direct_candidates if candidate in exchange_ids), None)

        if rid is None:
            hits = sorted(exchange_by_cpd.get(cpd, []))
            if len(hits) == 1:
                rid = hits[0]
            elif len(hits) > 1:
                # Prefer the clean community medium exchange if several exist.
                preferred = [h for h in hits if h == f"EX_{cpd}_m"]
                rid = preferred[0] if preferred else hits[0]

        if rid is not None and max_flux > 0:
            medium[rid] = max_flux
            status = "applied"
        elif rid is not None:
            status = "zero_flux"
        else:
            status = "missing"

        rows.append({
            "compound": cpd,
            "micom_exchange": rid or "",
            "maxFlux": max_flux,
            "status": status,
        })

    return medium, pd.DataFrame(rows)

